    "title": "新版《车用压缩天然气》强制性国家标准发布",
    "link": "https://36kr.com/newsflashes/3953145693650050?f=rss",
    "pub_date": "2026-08-24 14:27:45",
    "author": "",
    "description": "36氪获悉，近日，市场监管总局（国家标准委）批准发布《车用压缩天然气》（GB 18047—2026）强制性国家标准，将自2027年8月1日起实施。本次标准修订旨在提升产品质量、保障使用安全、促进贸易公平。该标准的发布实施将有效规范我国压缩天然气产品质量管控，促进车用压缩天然气行业高质量发展，保障天然气汽车正常运行，持续提升人民群众出行安全水平。",
