    "author": "",
    "description": "中新网北京8月24日电 (记者 应妮)23日晚，北京天桥艺术中心大剧场灯光渐暗，伴随着低音长笛的响起，一位身着西服、头戴礼帽的推销员威利·洛曼拿着两只硕大的箱子缓缓地走入舞台……这是上海话剧艺术中心制作出品的阿瑟·米勒经典话剧《推销员之死》开场，也是艺术家吕凉最后一次提着箱子走上舞台。",
    "content": "中新网北京8月24日电 (记者 应妮)23日晚，北京天桥艺术中心大剧场灯光渐暗，伴随着低音长笛的响起，一位身着西服、头戴礼帽的推销员威利·洛曼拿着两只硕大的箱子缓缓地走入舞台……这是上海话剧艺术中心制作出品的阿瑟·米勒经典话剧《推销员之死》开场，也是艺术家吕凉最后一次提着箱子走上舞台。"
