    "content": "现实中的婚恋有重重困境，而虚拟恋人却总细腻治愈。性别研究学者丁瑜历时五年，结合两万余份调查问卷与自身体验写成《虚拟恋人》一书。写作过程中，她沉入乙游圈层，访谈AI伴侣用户，在书中呈现了AI时代年轻人的多元情感面貌。8月22日晚间举办的《虚拟恋人》新书分享会中，主持人姜旭与本书作者丁瑜、中国人民大学新闻学院董晨宇，围绕乙女游戏、AI情感陪伴、新型亲密关系、玩家文化等话题展开对谈。 《虚拟恋人》新书分享会 始于好奇心，却慢慢上头 丁瑜《虚拟恋人》研究的起点并非大众熟知的乙女游戏《恋与深空》，而是淘宝早期的树洞陪聊服务，…"
