    "content": "2026年8月中旬，四川省凉山州德昌县茨达镇。群山环抱之中，一座崭新的篮球场迎来了它的揭幕时刻。站在球场中央的不是别人，而是NBA球星吉米·巴特勒。 这是巴特勒2026年中国行的第一站，他没有选择像北上广这样的一线城市，而是把首站给了这个地图上需要放大好几倍才能找到的小镇。 当记者问他为什么做出这个选择时，巴特勒的回答简短而笃定：“我不觉得大城市就是一切。” 他说：“我自己也来自一个小镇，那里也有很棒的篮球迷。如果只去大城市，那是不公平的。那些大城市当然很棒，但中国各个不同的地方都不可思议。你能看到山，看到绿色植被…"
