    "description": "巴克莱利率策略师在报告中表示，美联储主席沃什可能会主张减少美联储对前瞻指引的使用，因为他认为前瞻指引是过去政策失误的一个来源；预计沃什还将强调经济的长期驱动因素，尤其是生产率趋势及其对潜在增长的影响；沃什不太可能提供近期政策指引，但市场将寻求了解FOMC计划如何让通胀回到2%目标的更多信息。（财联社）",
