    "author": "“湖里头条”微信公号",
    "description": "厦门市湖里区联合调查组8月24日发布情况通报： 媒体报道我区一家场地消杀服务企业涉嫌违规开展消杀业务。此前，我区已接到群众举报并成立联合调查组，调查组当日对该企业消杀用品抽检取证，查扣企业剩余库存药品。目前企业在我区经营场所已关闭，下一步将根据调查情况依法依规严肃处理。同时，我区举一反三组织对辖区消杀企业进行全面排查整治，对违法违规行为将一查到底，绝不姑息。",
