    "description": "8月8日-9日，“学术、社会和中华民族认同——第五届学术社会史研讨会”在中央民族大学举办。会议由中央民族大学历史文化学院与国家社科基金中国历史研究院重大研究专项“近代以来国家仪式与中华民族认同研究”项目组联合主办，来自国内20多所高校和科研院所的50余位专家学者与会。本届会议旨在以学术社会史的研究视野与方法论，进一步深化中华民族历史与中华民族整体性认同等相关议题的研究。 在会议开幕式环节，中央民族大学党委常委、副校长彭勇教授进行了提纲挈…",
    "content": "8月8日-9日，“学术、社会和中华民族认同——第五届学术社会史研讨会”在中央民族大学举办。会议由中央民族大学历史文化学院与国家社科基金中国历史研究院重大研究专项“近代以来国家仪式与中华民族认同研究”项目组联合主办，来自国内20多所高校和科研院所的50余位专家学者与会。本届会议旨在以学术社会史的研究视野与方法论，进一步深化中华民族历史与中华民族整体性认同等相关议题的研究。 在会议开幕式环节，中央民族大学党委常委、副校长彭勇教授进行了提纲挈领的致辞。他表示，学术社会史主题会议已成功举办五届，在学术界产生了广泛的影响力。…"
