    "author": "",
    "description": "36氪获悉，企查查App显示，近日，贵州省金合产业并购股权投资基金合伙企业（有限合伙）成立，经营范围包含：以私募基金从事股权投资、投资管理、资产管理等活动。企查查股权穿透显示，该企业由贵州省贵鑫瑞和创业投资管理有限责任公司、贵州省国有资本运营有限责任公司共同出资。",
