    "title": "（活力中国调研行）“奔县”去山东：小城正成文旅新宠",
    "link": "https://www.chinanews.com.cn/cj/2026/08-24/10683104.shtml",
    "pub_date": "2026-08-24 13:45:31",
    "author": "",
    "description": "中新网济南8月24日电 (国璇 李明芮)随着“特种兵”式打卡游的热度降温，以慢节奏、深体验为特征的“慢充旅行”正悄然成为出游新风尚。山东省文化和旅游厅党组副书记、副厅长刘少华24日在“活力中国调研行”山东主题采访活动情况介绍会上透露，山东的县域文旅正告别千篇一律，“奔县游”正在山东多地持续升温。",
