    "content": "以色列总理内塔尼亚胡和国防部长卡茨23日警告巴勒斯坦伊斯兰抵抗运动（哈马斯），如果不立即停止从加沙地带向以色列“放风筝”，以军将加大对相关人员的打击力度，并疏散加沙地带相关区域居民。 内塔尼亚胡和卡茨当天晚间与以军总参谋长扎米尔等军方和国防部门高级官员举行形势评估会议，讨论近期加沙地带风筝飞入以色列境内事件。 据以媒报道，本周末至少有4只从加沙地带飞来的风筝落入以色列南部靠近加沙地带的集体农庄。以军表示，没有在这些风筝上发现可疑物品，风筝也未对公众构成危险。不过，这些风筝令人联想到此前数年从加沙地带放飞、携带燃烧装…"
