    "content": "新华社北京8月24日电 澳大利亚悉尼马拉松主办方23日在社交媒体上承认，本年度赛事的奖牌设计有误：奖牌图案原本应是悉尼安联球场，但刻成了德国慕尼黑安联球场。 德新社等多家媒体23日报道，2026年度悉尼马拉松的奖牌设计方案近日公布，这款双面奖牌刻有多处辨识度极高的悉尼地标，包括悉尼歌剧院、海港大桥，但球场却是慕尼黑的安联球场。 2025年8月31日，选手们从悉尼海港大桥上跑过。新华社记者马平摄 主办方23日在社交媒体上发文表示：“我们不会回避这件事。这是一次令人遗憾的失误，但无疑让大家这个周末多了谈资。” 主办方称…"
