    "author": "",
    "description": "随着比特币价格飙升，现货比特币交易所交易基金（ETF）上周录得10个月以来最强劲的单周资金流入。数据显示，13只在美国上市的基金净吸引资金19.2亿美元，创下去年10月以来的最高纪录。资金流入正逢比特币价格上周上涨约23%，创下三年多来最大单周涨幅。新加坡时间周一中午，比特币交易价格约为77000美元。（新浪财经）",
    "content": "随着比特币价格飙升，现货比特币交易所交易基金（ETF）上周录得10个月以来最强劲的单周资金流入。数据显示，13只在美国上市的基金净吸引资金19.2亿美元，创下去年10月以来的最高纪录。资金流入正逢比特币价格上周上涨约23%，创下三年多来最大单周涨幅。新加坡时间周一中午，比特币交易价格约为77000美元。（新浪财经）"
