    "description": "泰国财政部长周一表示，政府本周将与黄金协会讨论拟议中的税收措施。财政部长埃克尼蒂·尼蒂坦普拉帕斯表示，泰国将考虑对黄金交易和进口征税，并补充称，此举旨在遏制非法资金流动，无意高额征收黄金税。（财联社）",
