    "author": "",
    "description": "中新网8月24日电 据中央纪委国家监委驻国家电网有限公司纪检监察组、江苏省纪委监委消息：国网江苏省电力有限公司原三级顾问陈庆涉嫌严重违纪违法，目前正接受中央纪委国家监委驻国家电网有限公司纪检监察组纪律审查和江苏省南京市监察委员会监察调查。",
    "content": "中新网8月24日电 据中央纪委国家监委驻国家电网有限公司纪检监察组、江苏省纪委监委消息：国网江苏省电力有限公司原三级顾问陈庆涉嫌严重违纪违法，目前正接受中央纪委国家监委驻国家电网有限公司纪检监察组纪律审查和江苏省南京市监察委员会监察调查。"
