    "content": "IT之家 8 月 24 日消息，据中国汽车报今日报道，小米创办人、董事长兼 CEO 雷军在接受采访时，谈到了 推进汽车产业高端化相关话题。 雷军认为，中国汽车产业在接下来的发展中，高端化应该是较为确定的方向。 当前国内高端汽车市场处于产品青黄不接的状态 ，豪华车市场面临重构，中国汽车品牌正在不断成熟，而由于产品的供给出现不足，这个市场的年销量出现了较大幅度下滑。与此同时，中低端市场确实很卷，中高端市场则是缺少好的供给。 雷军表示，中国在 10 年前甚至 20 年前就已经实现大部分零部件产品的国产替代，整车设计和制造…"
