    "content": "新华社福州8月24日电（记者陈弘毅、张华迎）今年第20号台风“简拉维”将于今天白天在福建南部沿海登陆。根据有关规定，福建省防指24日提升防汛应急响应至三级，并维持防台风四级应急响应。 据福建省气象台消息，“简拉维”24日8时距离福建晋江东南方向约55公里，中心附近最大风力7级（热带低压级）。受其影响，今天福建沿海和南部地区有暴雨，其中福州和莆田两市的大部、平潭综合实验区、宁德和泉州两市的中东部，以及厦门、漳州和龙岩三市的局部有大暴雨，局部特大暴雨；其余地区局部大雨到暴雨。 气象专家提醒，相关区域航行或作业的船只注意…"
