    "description": "8月22日，第二届世界人形机器人运动会在国家速滑馆开幕，16个国家的666支赛队、2056台机器人参与竞逐。 本届运动会共设置51个项目、开展1301场比赛，将持续至26日。项目设置方面，在首届田径、足球等项目基础上，新增举重、拔河、乒乓球等项目，加大对机器人本体结构以及核心零部件的极限考验。 摄影：鞠焕宗 孙非 翟一凡 海报：张子彧 策划：孟丽静 施鳗珂 李雪",
    "content": "8月22日，第二届世界人形机器人运动会在国家速滑馆开幕，16个国家的666支赛队、2056台机器人参与竞逐。 本届运动会共设置51个项目、开展1301场比赛，将持续至26日。项目设置方面，在首届田径、足球等项目基础上，新增举重、拔河、乒乓球等项目，加大对机器人本体结构以及核心零部件的极限考验。 摄影：鞠焕宗 孙非 翟一凡 海报：张子彧 策划：孟丽静 施鳗珂 李雪"
