    "content": "“两类青年群体具有关联性，大学生若长期脱离学校、就业市场及社会关系网络，就可能从‘战略性休学’转向‘休息青年’高危群体。” 按照韩国官方定义，“休息青年”属于非经济活动人口中的一类——他们既不就业，也不积极求职，而是由于各种原因处于“休息状态”。正是这样，他们一般不纳入失业率的统计范围中。 “与其说‘优绩主义’已经崩塌，不如说它的‘回报机制’正在弱化。” 南方周末记者 陈相成 责任编辑：姚忆江 “间隔年” （Gap Year） 即将结束，25岁的韩国大学生朴善宇告诉南方周末记者，“这个过程并没有想象中顺利”。 20…"
