    "content": "2026年8月24日，澎湃新闻记者从上海蔬菜集团获悉，近日媒体报道河北张家口康保县部分白菜收购商涉嫌违规使用甲醛溶液保鲜一事，上海蔬菜集团高度重视，立即部署旗下各农产品批发市场启动应急响应机制。具体做法如下： 一、全面排查，不留死角。下属各农批市场对场内存量大白菜实施拉网式排查，逐批溯源，并同步开展抽样检测，确保风险隐患早发现、早处置。经核查，截至目前，未发现来自涉事康保县的问题白菜。 二、严格检测项目，严把准入关。自8月22日起，在严格执行“每批必检、先检后售”、索证索票等常规准入制度的基础上，针对所有进场大白菜…"
