    "title": "国际观察丨从“买不起”到“卖不动” 日本米价为何大起大落",
    "link": "http://www.news.cn/20260824/330815400fb84d3cbdb1276e79c029df/c.html",
    "pub_date": "2026-08-24 11:24:10",
    "author": "李诗萌,蓝建中",
    "description": "新华社东京8月24日电 题：从“买不起”到“卖不动” 日本米价为何大起大落 新华社记者李诗萌 蓝建中 寿司、饭团、咖喱饭、鳗鱼饭……大米几乎贯穿日本民众的一日三餐。然而，过去一年多时间里，日本米价变化如同“过山车”：2024年夏天开始，米价持续上涨，一度演变成“大米荒”；今年年初以来，随着库存增加和新米上市，米价又快速回落，部分产区农民甚至面临亏本卖米。 分析人士认为，从消费者“买不起”到经营者“卖不动”，背后是日本大米市场供需关系的失…",
    "content": "新华社东京8月24日电 题：从“买不起”到“卖不动” 日本米价为何大起大落 新华社记者李诗萌 蓝建中 寿司、饭团、咖喱饭、鳗鱼饭……大米几乎贯穿日本民众的一日三餐。然而，过去一年多时间里，日本米价变化如同“过山车”：2024年夏天开始，米价持续上涨，一度演变成“大米荒”；今年年初以来，随着库存增加和新米上市，米价又快速回落，部分产区农民甚至面临亏本卖米。 分析人士认为，从消费者“买不起”到经营者“卖不动”，背后是日本大米市场供需关系的失衡。若米价继续下跌，可能打击农民种植积极性，进一步削弱日本农业生产基础。 米价大…"
