    "content": "目前，我国夏粮旺季收购进入高峰。国家粮食和物资储备局24日发布最新数据显示，全国各类粮食经营主体累计收购小麦超9000万吨。南方早籼稻迎来集中上市。各地收购工作有序开展，收购进展整体顺利。 国家粮食和物资储备局有关负责同志表示，为保护种粮农民利益，8月以来，国家有关部门先后在江西、湖南两省启动早籼稻最低收购价执行预案，在河南省启动小麦最低收购价执行预案，发挥政策托底作用，稳定市场预期。 下一步，国家粮食和物资储备局将坚持市场化收购和政策性收储相结合，持续跟踪降雨等天气变化，指导有关省份强化烘干收储，优化收购安排，帮…"
