    "description": "新华社利马8月23日电 通讯｜“在我心里，中国是第二故乡”——一名秘鲁罕见病患者的重生之旅 新华社记者廖思维 王植樱 “我从没想过有一天能拍出这么漂亮的照片。”回想起去年10月身穿中国传统服饰在北京故宫拍照的情景，40岁的秘鲁女子马加莉·罗马尼笑着说，“曾经关闭的一扇门，终于重新打开了。” 这一刻，她等了20多年。 18岁时，马加莉的身体多处开始出现细小丘疹。起初，医生以为只是普通皮肤问题，然而丘疹非但没有消退，反而不断蔓延，并累及关节…",
    "content": "新华社利马8月23日电 通讯｜“在我心里，中国是第二故乡”——一名秘鲁罕见病患者的重生之旅 新华社记者廖思维 王植樱 “我从没想过有一天能拍出这么漂亮的照片。”回想起去年10月身穿中国传统服饰在北京故宫拍照的情景，40岁的秘鲁女子马加莉·罗马尼笑着说，“曾经关闭的一扇门，终于重新打开了。” 这一刻，她等了20多年。 18岁时，马加莉的身体多处开始出现细小丘疹。起初，医生以为只是普通皮肤问题，然而丘疹非但没有消退，反而不断蔓延，并累及关节、双眼和咽喉部，造成视力受损和呼吸困难。经诊断，她患上了全球确诊病例不足200例…"
